{
  "items": [
    {
      "name": "MvPolynomial.coeffs_zero",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] : MvPolynomial.coeffs 0 = ∅",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_zero_X",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (i : σ) : (MvPolynomial.X i).coeff 0 = 0",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_zero",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] : AddMonoidAlgebra.coeff 0 = 0",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_zero_one",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] : (AddMonoidAlgebra.coeff 1) 0 = 1",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeffs_C",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] [DecidableEq R] (r : R) : (MvPolynomial.C r).coeffs = if r = 0 then ∅ else {r}",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_single_X",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] [DecidableEq σ] (s s' : σ) (n : ℕ) : ((MvPolynomial.X s).coeff fun₀ | s' => n) = if n = 1 ∧ s = s' then 1 else 0",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_X",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] [DecidableEq σ] (i : σ) (m : σ →₀ ℕ) : (MvPolynomial.X i).coeff m = if (fun₀ | i => 1) = m then 1 else 0",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_X'",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] [DecidableEq σ] (i : σ) (m : σ →₀ ℕ) : (MvPolynomial.X i).coeff m = if (fun₀ | i => 1) = m then 1 else 0",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_zero_C",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (a : R) : (MvPolynomial.C a).coeff 0 = a",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_mem_coeffs",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {p : MvPolynomial σ R} (m : σ →₀ ℕ) (h : p.coeff m ≠ 0) : p.coeff m ∈ p.coeffs",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_C_of_ne_zero",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] {m : σ →₀ ℕ} (h : m ≠ 0) (a : R) : (MvPolynomial.C a).coeff m = 0",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_X_pow",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] [DecidableEq σ] (i : σ) (m : σ →₀ ℕ) (k : ℕ) : (MvPolynomial.X i ^ k).coeff m = if (fun₀ | i => k) = m then 1 else 0",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    }
  ]
}
